{"command": "cat > /workspace/compose_patterns3.py << 'PYEOF'
import json
import subprocess

def ft2_call(tool, args):
    cmd = f"ft2 call {tool} '{json.dumps(args)}'"
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    if result.returncode != 0:
        print(f"ERROR: {result.stderr}")
    return result.stdout.strip()

C, Cs, D, Ds, E, F, Fs, G, Gs, A, As, B = range(12)

def note(octave, semitone):
    return (octave - 1) * 12 + semitone + 1

def n(oct, semi):
    return note(oct, semi)

chords = [
    (n(2, A), "Am"),
    (n(2, F), "F"),
    (n(2, C), "C"),
    (n(2, G), "G")
]

arp_chords = [
    [n(4, A), n(4, C), n(4, E), n(5, A)],
    [n(4, F), n(4, A), n(5, C), n(5, F)],
    [n(4, C), n(4, E), n(4, G), n(5, C)],
    [n(4, G), n(4, B), n(4, D), n(5, G)]
]

# Pattern 4: Full B - Pattern 2 melody with pads and full drums
print("Composing Pattern 4 (Full B)...")
for row in range(0, 64, 4):
    ft2_call("pattern_set_cell", {"pattern": 4, "row": row, "channel": 4, "note": n(3, C), "instrument": 4, "volume": 56})
for row in range(4, 64, 8):
    ft2_call("pattern_set_cell", {"pattern": 4, "row": row, "channel": 5, "note": n(4, C), "instrument": 5, "volume": 48})
for row in range(0, 64, 2):
    ft2_call("pattern_set_cell", {"pattern": 4, "row": row, "channel": 6, "note": n(5, C), "instrument": 6, "volume": 32})
for row in range(1, 64, 2):
    ft2_call("pattern_set_cell", {"pattern": 4, "row": row, "channel": 6, "note": n(5, C), "instrument": 6, "volume": 24})

# Bass
for i, (root, name) in enumerate(chords):
    start = i * 16
    for r in range(0, 16, 2):
        ft2_call("pattern_set_cell", {"pattern": 4, "row": start + r, "channel": 3, "note": root, "instrument": 2, "volume": 52})

# Pad
pad_roots = [n(3, A), n(3, F), n(3, C), n(3, G)]
for i, root in enumerate(pad_roots):
    row = i * 16
    ft2_call("pattern_set_cell", {"pattern": 4, "row": row, "channel": 7, "note": root, "instrument": 7, "volume": 36})

# Arpeggios with descending/ascending pattern
for i, chord in enumerate(arp_chords):
    start = i * 16
    for r in range(16):
        idx = [0,1,2,3,2,1,0,3][r % 8]
        note_val = chord[idx]
        ft2_call("pattern_set_cell", {"pattern": 4, "row": start + r, "channel": 1, "note": note_val, "instrument": 3, "volume": 36})
        if r < 15:
            idx2 = [3,2,1,0,1,2,3,0][(r+1) % 8]
            note_val2 = chord[idx2]
            ft2_call("pattern_set_cell", {"pattern": 4, "row": start + r + 1, "channel": 2, "note": note_val2, "instrument": 8, "volume": 32})

# Lead melody B variation
melody_b_am = [
    (0, n(5, A)), (3, n(5, C)), (6, n(5, E)), (9, n(5, A)),
    (12, n(5, G)), (14, n(5, E))
]
for row, note_val in melody_b_am:
    ft2_call("pattern_set_cell", {"pattern": 4, "row": row, "channel": 0, "note": note_val, "instrument": 1, "volume": 48})

melody_b_f = [
    (16, n(5, F)), (19, n(5, A)), (22, n(5, C)), (25, n(5, F)),
    (28, n(5, A)), (30, n(5, C))
]
for row, note_val in melody_b_f:
    ft2_call("pattern_set_cell", {"pattern": 4, "row": row, "channel": 0, "note": note_val, "instrument": 1, "volume": 48})

melody_b_c = [
    (32, n(5, C)), (35, n(5, E)), (38, n(5, G)), (41, n(5, C)),
    (44, n(5, E)), (46, n(5, G))
]
for row, note_val in melody_b_c:
    ft2_call("pattern_set_cell", {"pattern": 4, "row": row, "channel": 0, "note": note_val, "instrument": 1, "volume": 48})

melody_b_g = [
    (48, n(4, G)), (51, n(4, B)), (54, n(5, D)), (57, n(5, G)),
    (60, n(5, B)), (62, n(5, D))
]
for row, note_val in melody_b_g:
    ft2_call("pattern_set_cell", {"pattern": 4, "row": row, "channel": 0, "note": note_val, "instrument": 1, "volume": 48})

print("Pattern 4 done")

# Pattern 5: Loop back to pattern 1 (Main A)
# Just use pattern 1 in the order list, already set up
# Actually pattern 5 is not needed since we loop back to pattern 1 in the order

print("All patterns complete!")
